export interface UserProfile {
  name: string;
  goal: 'Bulk' | 'Cut' | 'Maintain';
  dailyCalorieGoal: number;
  macros: {
    protein: number;
    carbs: number;
    fats: number;
    fiber: number;
  };
}

export interface FoodEntry {
  id: string;
  name: string;
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  fiber: number;
  timestamp: Date;
}

export interface NutritionData {
  foodName: string;
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  fiber: number;
}

export type View = 'home' | 'analytics' | 'diary' | 'recipes' | 'profile' | 'camera' | 'auth';

import { GoogleGenAI, Type } from "@google/genai";
import { NutritionData } from "../types";

export const analyzeFoodImage = async (base64Image: string): Promise<NutritionData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: "Analyze this food image and identify the primary dish. Provide its estimated nutritional values for a standard serving. If it's an Indian dish, be culturally accurate. Return ONLY a JSON object.",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          calories: { type: Type.NUMBER },
          protein: { type: Type.NUMBER },
          carbs: { type: Type.NUMBER },
          fats: { type: Type.NUMBER },
          fiber: { type: Type.NUMBER },
        },
        required: ["foodName", "calories", "protein", "carbs", "fats", "fiber"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text) as NutritionData;
};

