import React, { useState, useRef } from 'react';
import { analyzeFoodImage } from '../services/geminiService';
import { NutritionData } from '../types';

interface CameraScanProps {
  onAddEntry: (data: NutritionData) => void;
  onClose: () => void;
}

const CameraScan: React.FC<CameraScanProps> = ({ onAddEntry, onClose }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<NutritionData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setImage(base64);
      setLoading(true);
      setError(null);

      try {
        const base64Data = base64.split(',')[1];
        const nutrition = await analyzeFoodImage(base64Data);
        setResult(nutrition);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze food. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmAdd = () => {
    if (result) {
      onAddEntry(result);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-background-dark z-[100] flex flex-col items-center p-6">
      <div className="w-full flex justify-between items-center mb-6">
        <button onClick={onClose} className="p-2 bg-white/5 rounded-full text-white">
          <span className="material-icons-round">close</span>
        </button>
        <h2 className="text-lg font-bold">NutriVision AI</h2>
        <div className="w-10"></div>
      </div>

      {!image ? (
        <div className="flex-1 flex flex-col items-center justify-center text-center space-y-8">
          <div className="w-64 h-64 border-2 border-dashed border-primary/30 rounded-3xl flex items-center justify-center bg-primary/5">
            <span className="material-icons-round text-6xl text-primary/40">photo_library</span>
          </div>
          <div className="space-y-2">
            <h3 className="text-xl font-bold">Snap Your Meal</h3>
            <p className="text-slate-400 text-sm px-8">Our AI identifies the food and calculates macros instantly</p>
          </div>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="bg-primary text-black font-bold px-12 py-4 rounded-xl shadow-lg fab-glow"
          >
            SELECT IMAGE
          </button>
          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            ref={fileInputRef}
            onChange={handleFileChange}
          />
        </div>
      ) : (
        <div className="flex-1 w-full flex flex-col space-y-6">
          <div className="relative w-full aspect-square rounded-3xl overflow-hidden border border-white/10 shadow-xl">
            <img src={image} alt="Food" className="w-full h-full object-cover" />
            {loading && (
              <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                <p className="mt-4 text-primary font-bold animate-pulse">Analyzing with AI...</p>
              </div>
            )}
          </div>

          {result && (
            <div className="glass-card rounded-2xl p-6 space-y-4 animate-in fade-in slide-in-from-bottom-4">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-xl font-bold text-primary">{result.foodName}</h3>
                  <p className="text-slate-400 text-sm">Nutritional Estimate</p>
                </div>
                <div className="text-right">
                  <p className="text-2xl font-bold">{result.calories}</p>
                  <p className="text-[10px] uppercase font-bold text-slate-500">kcal</p>
                </div>
              </div>

              <div className="grid grid-cols-4 gap-2">
                <div className="text-center p-2 bg-white/5 rounded-lg">
                  <p className="text-xs font-bold">{result.protein}g</p>
                  <p className="text-[8px] text-slate-500 uppercase">Protein</p>
                </div>
                <div className="text-center p-2 bg-white/5 rounded-lg">
                  <p className="text-xs font-bold">{result.carbs}g</p>
                  <p className="text-[8px] text-slate-500 uppercase">Carbs</p>
                </div>
                <div className="text-center p-2 bg-white/5 rounded-lg">
                  <p className="text-xs font-bold">{result.fats}g</p>
                  <p className="text-[8px] text-slate-500 uppercase">Fats</p>
                </div>
                <div className="text-center p-2 bg-white/5 rounded-lg">
                  <p className="text-xs font-bold">{result.fiber}g</p>
                  <p className="text-[8px] text-slate-500 uppercase">Fiber</p>
                </div>
              </div>

              <button 
                onClick={confirmAdd}
                className="w-full bg-primary text-black font-bold py-4 rounded-xl shadow-lg active:scale-[0.98] transition-all"
              >
                Log to Diary
              </button>
            </div>
          )}

          {error && (
            <div className="bg-red-500/10 border border-red-500/50 p-4 rounded-xl text-red-400 text-center text-sm">
              {error}
              <button 
                onClick={() => setImage(null)}
                className="block mx-auto mt-2 font-bold underline"
              >
                Try Another
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default CameraScan;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import CameraScan from './components/CameraScan';
import Auth from './components/Auth';
import { View, UserProfile, FoodEntry, NutritionData } from './types';

const App: React.FC = () => {
  const [view, setView] = useState<View>('auth');
  const [user, setUser] = useState<UserProfile>({
    name: 'Alex',
    goal: 'Maintain',
    dailyCalorieGoal: 2250,
    macros: {
      protein: 150,
      carbs: 250,
      fats: 75,
      fiber: 35
    }
  });

  const [entries, setEntries] = useState<FoodEntry[]>([
    {
      id: '1',
      name: 'Oats & Banana',
      calories: 450,
      protein: 15,
      carbs: 70,
      fats: 8,
      fiber: 12,
      timestamp: new Date()
    },
    {
      id: '2',
      name: 'Chicken Breast with Salad',
      calories: 560,
      protein: 75,
      carbs: 35,
      fats: 12,
      fiber: 8,
      timestamp: new Date()
    }
  ]);

  const handleAddEntry = (data: NutritionData) => {
    const newEntry: FoodEntry = {
      id: Math.random().toString(36).substr(2, 9),
      name: data.foodName,
      calories: data.calories,
      protein: data.protein,
      carbs: data.carbs,
      fats: data.fats,
      fiber: data.fiber,
      timestamp: new Date()
    };
    setEntries(prev => [...prev, newEntry]);
    setView('home');
  };

  const handleLogin = (name: string) => {
    setUser(prev => ({ ...prev, name }));
    setView('home');
  };

  const renderContent = () => {
    switch (view) {
      case 'home':
        return <Dashboard user={user} entries={entries} />;
      case 'analytics':
        return <Analytics />;
      case 'camera':
        return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      case 'auth':
        return <Auth onLogin={handleLogin} />;
      default:
        return (
          <div className="flex flex-col items-center justify-center h-full text-slate-500">
            <span className="material-icons-round text-6xl mb-4">construction</span>
            <p className="font-medium">{view.toUpperCase()} Screen Under Development</p>
            <button 
              onClick={() => setView('home')}
              className="mt-6 text-primary font-bold"
            >
              Back to Dashboard
            </button>
          </div>
        );
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
};

export default App;

