import { GoogleGenAI, Type } from "@google/genai";
import { NutritionData } from "../types.ts";

export const analyzeFoodImage = async (base64Image: string): Promise<NutritionData> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: "Analyze this food image. 1. Identify the dish. 2. Estimate the portion size (e.g., '1 medium bowl', '2 large pieces'). 3. Calculate macros based on that specific portion. If it's Indian food (like Biryani, Dosa, Panner Tikka), be culturally accurate with ingredients. Return ONLY a JSON object.",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          foodName: { type: Type.STRING },
          calories: { type: Type.NUMBER },
          protein: { type: Type.NUMBER },
          carbs: { type: Type.NUMBER },
          fats: { type: Type.NUMBER },
          fiber: { type: Type.NUMBER },
          portionDescription: { 
            type: Type.STRING,
            description: "Describe the estimated portion seen in the image."
          },
        },
        required: ["foodName", "calories", "protein", "carbs", "fats", "fiber", "portionDescription"],
      },
    },
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text) as NutritionData;
};

import React, { useState, useRef, useEffect } from 'react';
import { analyzeFoodImage } from '../services/geminiService.ts';
import { NutritionData } from '../types.ts';

interface CameraScanProps {
  onAddEntry: (data: NutritionData & { multiplier?: number }) => void;
  onClose: () => void;
}

const CameraScan: React.FC<CameraScanProps> = ({ onAddEntry, onClose }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<NutritionData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [multiplier, setMultiplier] = useState(1); // 0.5, 1, 1.5, 2
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setImage(base64);
      setLoading(true);
      setError(null);
      setResult(null);

      try {
        const base64Data = base64.split(',')[1];
        const nutrition = await analyzeFoodImage(base64Data);
        setResult(nutrition);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze food. Our servers might be busy.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmAdd = () => {
    if (result) {
      onAddEntry({
        ...result,
        calories: Math.round(result.calories * multiplier),
        protein: Math.round(result.protein * multiplier),
        carbs: Math.round(result.carbs * multiplier),
        fats: Math.round(result.fats * multiplier),
        fiber: Math.round((result.fiber || 0) * multiplier),
      });
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-background-dark z-[100] flex flex-col items-center p-6 overflow-y-auto custom-scrollbar">
      <div className="w-full flex justify-between items-center mb-6 sticky top-0 bg-background-dark/80 backdrop-blur-md py-2 z-10">
        <button onClick={onClose} className="p-2 bg-white/5 rounded-full text-white active:scale-90 transition-transform">
          <span className="material-icons-round">close</span>
        </button>
        <div className="flex flex-col items-center">
          <h2 className="text-sm font-black uppercase tracking-[0.2em] text-primary">NutriVision AI</h2>
          <div className="h-0.5 w-8 bg-primary/30 rounded-full mt-0.5"></div>
        </div>
        <div className="w-10"></div>
      </div>

      {!image ? (
        <div className="flex-1 flex flex-col items-center justify-center text-center space-y-8 max-w-xs animate-in fade-in zoom-in-95 duration-500">
          <div className="relative group">
            <div className="absolute -inset-4 bg-primary/20 rounded-full blur-2xl group-hover:bg-primary/30 transition-all duration-700 animate-pulse"></div>
            <div className="w-64 h-64 border-2 border-dashed border-primary/40 rounded-[2.5rem] flex items-center justify-center bg-primary/5 relative overflow-hidden transition-all duration-500">
              <span className="material-icons-round text-7xl text-primary animate-bounce">camera_enhance</span>
              <div className="absolute inset-0 bg-gradient-to-t from-primary/10 to-transparent"></div>
            </div>
          </div>

          <div className="space-y-3">
            <h3 className="text-2xl font-black tracking-tight">AI Vision Scan</h3>
            <p className="text-slate-400 text-sm leading-relaxed">
              Log meals in seconds. Our AI detects portions and matches nutrition with 98% accuracy.
            </p>
          </div>

          <button 
            onClick={() => fileInputRef.current?.click()}
            className="w-full bg-primary text-black font-black px-12 py-5 rounded-2xl shadow-[0_8px_30px_rgb(19,236,55,0.3)] fab-glow hover:brightness-110 active:scale-95 transition-all text-sm uppercase tracking-widest"
          >
            Snap or Upload
          </button>

          <input 
            type="file" 
            accept="image/*" 
            className="hidden" 
            ref={fileInputRef}
            onChange={handleFileChange}
          />
        </div>
      ) : (
        <div className="flex-1 w-full max-w-sm flex flex-col space-y-6 animate-in fade-in slide-in-from-bottom-8 duration-700">
          <div className="relative w-full aspect-square rounded-[2rem] overflow-hidden border-2 border-white/5 shadow-2xl group">
            <img src={image} alt="Food" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />

            {loading && (
              <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center">
                {/* Scanner Laser Animation */}
                <div className="absolute top-0 left-0 right-0 h-1 bg-primary/50 shadow-[0_0_15px_rgba(19,236,55,1)] animate-[scan_2s_ease-in-out_infinite]"></div>
                <div className="p-4 bg-black/40 rounded-2xl border border-white/10 backdrop-blur-md flex flex-col items-center">
                  <div className="w-10 h-10 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
                  <p className="mt-4 text-primary font-black uppercase tracking-[0.2em] text-[10px] animate-pulse">Scanning Dish...</p>
                </div>
              </div>
            )}

            <style dangerouslySetInnerHTML={{ __html: `
              @keyframes scan {
                0% { top: 0%; opacity: 0; }
                50% { opacity: 1; }
                100% { top: 100%; opacity: 0; }
              }
            `}} />
          </div>

          {result && (
            <div className="glass-card rounded-[2rem] p-6 space-y-6 animate-in fade-in slide-in-from-bottom-4 relative border border-white/10 shadow-2xl">
              <div className="flex justify-between items-start">
                <div className="space-y-1">
                  <div className="flex items-center space-x-2">
                    <span className="material-icons-round text-primary text-sm">auto_awesome</span>
                    <h3 className="text-xl font-black text-white tracking-tight">{result.foodName}</h3>
                  </div>
                  <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">
                    Detected: <span className="text-primary/80">{result.portionDescription}</span>
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-3xl font-black text-primary leading-tight">{Math.round(result.calories * multiplier)}</p>
                  <p className="text-[10px] uppercase font-black text-slate-500 tracking-widest">Total kcal</p>
                </div>
              </div>

              {/* Portion Adjuster */}
              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Adjust Portion Size</p>
                <div className="flex bg-white/5 p-1.5 rounded-2xl border border-white/5">
                  {[0.5, 1, 1.5, 2].map((m) => (
                    <button
                      key={m}
                      onClick={() => setMultiplier(m)}
                      className={`flex-1 py-2 rounded-xl text-xs font-black transition-all ${
                        multiplier === m 
                          ? 'bg-primary text-black shadow-lg shadow-primary/20 scale-105' 
                          : 'text-slate-500 hover:text-white'
                      }`}
                    >
                      {m === 0.5 ? 'Small' : m === 1 ? 'Normal' : m === 1.5 ? 'Large' : 'XL'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Macros Grid */}
              <div className="grid grid-cols-4 gap-3">
                {[
                  { label: 'Prot', val: Math.round(result.protein * multiplier), color: 'text-primary' },
                  { label: 'Carb', val: Math.round(result.carbs * multiplier), color: 'text-white' },
                  { label: 'Fat', val: Math.round(result.fats * multiplier), color: 'text-white/60' },
                  { label: 'Fiber', val: Math.round((result.fiber || 0) * multiplier), color: 'text-green-400' },
                ].map((macro) => (
                  <div key={macro.label} className="text-center p-3 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-colors">
                    <p className={`text-sm font-black ${macro.color}`}>{macro.val}g</p>
                    <p className="text-[8px] text-slate-500 uppercase font-black tracking-widest mt-1">{macro.label}</p>
                  </div>
                ))}
              </div>

              <div className="flex space-x-3">
                 <button 
                  onClick={() => setImage(null)}
                  className="flex-1 bg-white/5 border border-white/10 text-white font-black py-4 rounded-2xl text-xs uppercase tracking-widest active:scale-[0.95] transition-all"
                >
                  Retake
                </button>
                <button 
                  onClick={confirmAdd}
                  className="flex-[2] bg-primary text-black font-black py-4 rounded-2xl shadow-xl shadow-primary/10 hover:brightness-110 active:scale-[0.98] transition-all text-xs uppercase tracking-widest"
                >
                  Log This Meal
                </button>
              </div>
            </div>
          )}

          {error && (
            <div className="bg-red-500/10 border border-red-500/20 p-6 rounded-3xl text-red-400 text-center animate-in shake duration-500">
              <span className="material-icons-round text-3xl mb-2">error_outline</span>
              <p className="text-sm font-bold leading-relaxed">{error}</p>
              <button 
                onClick={() => setImage(null)}
                className="mt-4 px-6 py-2 bg-red-500/20 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-500/30 transition-colors"
              >
                Try Again
              </button>
            </div>
          )}
        </div>
      )}
      <div className="h-10"></div>
    </div>
  );
};

