import React, { useState } from 'react';
import { FoodEntry, NutritionData } from '../types.ts';

interface DiaryProps {
  entries: FoodEntry[];
  onAddManualEntry: (data: NutritionData) => void;
}

export default function Diary({ entries, onAddManualEntry }: DiaryProps) {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [isAdding, setIsAdding] = useState(false);

  // Manual Entry Form State
  // Fix: Added missing portionDescription property to the initial state
  const [formData, setFormData] = useState<NutritionData>({
    foodName: '',
    calories: 0,
    protein: 0,
    carbs: 0,
    fats: 0,
    fiber: 0,
    portionDescription: ''
  });

  const filteredEntries = entries.filter(entry => {
    const entryDate = new Date(entry.timestamp).toISOString().split('T')[0];
    return entryDate === selectedDate;
  }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

  const dailyTotals = filteredEntries.reduce((acc, e) => ({
    cal: acc.cal + e.calories,
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
  }), { cal: 0, p: 0, c: 0, f: 0 });

  const handleSaveManual = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.foodName) return;
    onAddManualEntry(formData);
    setIsAdding(false);
    // Fix: Added missing portionDescription property to the reset state
    setFormData({ foodName: '', calories: 0, protein: 0, carbs: 0, fats: 0, fiber: 0, portionDescription: '' });
  };

  return (
    <div className="space-y-6">
      <header className="space-y-4">
        <div className="flex justify-between items-center">
          <h1 className="text-2xl font-bold">Food Diary</h1>
          <button 
            onClick={() => setIsAdding(true)}
            className="flex items-center space-x-1 bg-primary text-black px-3 py-1.5 rounded-lg font-bold text-xs shadow-lg active:scale-95 transition-transform"
          >
            <span className="material-icons-round text-sm">add</span>
            <span>Quick Add</span>
          </button>
        </div>

        <div className="glass-card rounded-xl p-3 flex items-center space-x-3">
          <span className="material-icons-round text-primary">calendar_today</span>
          <input 
            type="date" 
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            className="bg-transparent text-sm font-medium focus:outline-none w-full text-white scheme-dark"
          />
        </div>
      </header>

      {/* Manual Entry Modal */}
      {isAdding && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md">
          <div className="glass-card w-full max-w-[380px] rounded-3xl p-6 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold">Quick Log</h3>
              <button onClick={() => setIsAdding(false)} className="text-slate-400">
                <span className="material-icons-round">close</span>
              </button>
            </div>

            <form onSubmit={handleSaveManual} className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] uppercase font-bold text-slate-500 ml-1">Food Name</label>
                <input 
                  autoFocus
                  required
                  value={formData.foodName}
                  onChange={e => setFormData({...formData, foodName: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 focus:border-primary outline-none"
                  placeholder="e.g. Protein Shake"
                />
              </div>

              {/* Added portionDescription input field */}
              <div className="space-y-1">
                <label className="text-[10px] uppercase font-bold text-slate-500 ml-1">Portion Size</label>
                <input 
                  value={formData.portionDescription}
                  onChange={e => setFormData({...formData, portionDescription: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 focus:border-primary outline-none"
                  placeholder="e.g. 1 serving, 250g"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] uppercase font-bold text-slate-500 ml-1">Calories (kcal)</label>
                  <input 
                    type="number"
                    value={formData.calories || ''}
                    onChange={e => setFormData({...formData, calories: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 focus:border-primary outline-none"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] uppercase font-bold text-slate-500 ml-1">Protein (g)</label>
                  <input 
                    type="number"
                    value={formData.protein || ''}
                    onChange={e => setFormData({...formData, protein: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 focus:border-primary outline-none"
                    placeholder="0"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] uppercase font-bold text-slate-500 ml-1">Carbs (g)</label>
                  <input 
                    type="number"
                    value={formData.carbs || ''}
                    onChange={e => setFormData({...formData, carbs: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 focus:border-primary outline-none"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] uppercase font-bold text-slate-500 ml-1">Fats (g)</label>
                  <input 
                    type="number"
                    value={formData.fats || ''}
                    onChange={e => setFormData({...formData, fats: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-4 focus:border-primary outline-none"
                    placeholder="0"
                  />
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-primary text-black font-bold py-4 rounded-xl shadow-lg mt-4 active:scale-[0.98] transition-all"
              >
                Log Entry
              </button>
            </form>
          </div>
        </div>
      )}

      {filteredEntries.length > 0 && (
        <section className="bg-primary/5 border border-primary/20 rounded-2xl p-5 grid grid-cols-4 gap-2">
          <div className="text-center">
            <p className="text-[10px] text-slate-500 uppercase font-bold">Calories</p>
            <p className="text-lg font-bold text-primary">{Math.round(dailyTotals.cal)}</p>
          </div>
          <div className="text-center">
            <p className="text-[10px] text-slate-500 uppercase font-bold">Prot</p>
            <p className="text-lg font-bold">{Math.round(dailyTotals.p)}g</p>
          </div>
          <div className="text-center">
            <p className="text-[10px] text-slate-500 uppercase font-bold">Carbs</p>
            <p className="text-lg font-bold">{Math.round(dailyTotals.c)}g</p>
          </div>
          <div className="text-center">
            <p className="text-[10px] text-slate-500 uppercase font-bold">Fats</p>
            <p className="text-lg font-bold">{Math.round(dailyTotals.f)}g</p>
          </div>
        </section>
      )}

      <section className="space-y-4">
        <h2 className="text-xs font-semibold uppercase tracking-widest text-slate-400">Meals & Snacks</h2>

        {filteredEntries.length === 0 ? (
          <div className="py-12 flex flex-col items-center text-center space-y-4 opacity-40">
            <span className="material-icons-round text-6xl">no_food</span>
            <p className="text-sm font-medium px-12 italic">No entries logged for this date. Time to snap some food!</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filteredEntries.map((entry) => (
              <div key={entry.id} className="glass-card rounded-xl p-4 flex items-center justify-between group active:scale-[0.98] transition-all">
                <div className="space-y-1">
                  <div className="flex items-center space-x-2">
                    <span className="text-[10px] text-primary/60 font-bold uppercase">
                      {new Date(entry.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                    <h3 className="text-sm font-bold truncate max-w-[150px]">{entry.name}</h3>
                  </div>
                  <div className="flex space-x-3">
                    <span className="text-[10px] text-slate-400">P: <span className="text-white font-medium">{Math.round(entry.protein)}g</span></span>
                    <span className="text-[10px] text-slate-400">C: <span className="text-white font-medium">{Math.round(entry.carbs)}g</span></span>
                    <span className="text-[10px] text-slate-400">F: <span className="text-white font-medium">{Math.round(entry.fats)}g</span></span>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-lg font-black text-primary leading-none">{entry.calories}</p>
                  <p className="text-[9px] uppercase font-bold text-slate-500">kcal</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <div className="pb-10"></div>
    </div>
  );
}

