          <div className="flex-1 h-px bg-white/5"></div>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full">
          <button 
            type="button"
            onClick={handleGoogleLogin}
            className="flex items-center justify-center space-x-3 bg-white/5 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-colors active:scale-95"
          >
            <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-5 h-5" alt="Google" />
            <span className="text-xs font-black uppercase tracking-widest">Google</span>
          </button>
          <button 
            type="button"
            className="flex items-center justify-center space-x-3 bg-white/5 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-colors active:scale-95"
          >
            <span className="material-icons-round">apple</span>
            <span className="text-xs font-black uppercase tracking-widest">Apple</span>
          </button>
        </div>

        <div className="mt-auto pt-12 pb-6 text-center">
          <p className="text-white/40 text-[10px] font-black uppercase tracking-widest">
            {isLogin ? "Need an account?" : "Have an account?"}
            <button 
              onClick={() => setIsLogin(!isLogin)}
              className="text-primary font-black ml-2 hover:underline focus:outline-none"
            >
              {isLogin ? 'Join Now' : 'Login'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

