    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      setImage(base64);
      setLoading(true);
      setError(null);
      setResult(null);

      try {
        const base64Data = base64.split(',')[1];
        const nutrition = await analyzeFoodImage(base64Data);
        setResult(nutrition);
      } catch (err) {
        console.error(err);
        setError("Failed to analyze food. Our servers might be busy.");
      } finally {
        setLoading(false);
      }
    };
    reader.readAsDataURL(file);
  };

