import React, { useState } from 'react';
import { auth } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  GoogleAuthProvider, 
  signInWithPopup 
} from 'firebase/auth';

interface AuthProps {
  onLogin: (name: string, email: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      if (isLogin) {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        onLogin(userCredential.user.displayName || 'User', userCredential.user.email || '');
      } else {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        onLogin(name || 'New User', userCredential.user.email || '');
      }
    } catch (err: any) {
      setError(err.message || 'Authentication failed. Please check your credentials.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(auth, provider);
      onLogin(result.user.displayName || 'Google User', result.user.email || '');
    } catch (err: any) {
      setError(err.message || 'Google login failed.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-background-dark">
      {isLoading && (
        <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-primary font-bold animate-pulse uppercase tracking-widest text-xs">Authenticating...</p>
        </div>
      )}

      <div className="w-full max-w-[430px] flex flex-col items-center p-8 relative overflow-hidden">
        <div className="absolute top-[-10%] left-[-20%] w-[80%] h-[80%] bg-primary/20 blur-[120px] rounded-full -z-10"></div>
        <div className="absolute bottom-[-10%] right-[-20%] w-[60%] h-[60%] bg-primary/10 blur-[100px] rounded-full -z-10"></div>

        <div className="mt-20 mb-12 text-center">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-primary/10 rounded-2xl mb-4 border border-primary/20 shadow-[0_0_30px_rgba(19,236,55,0.2)]">
            <span className="material-icons-round text-primary text-5xl">bolt</span>
          </div>
          <h1 className="text-4xl font-black tracking-tight italic">NutriVision <span className="text-primary not-italic">AI</span></h1>
          <p className="text-white/40 mt-2 font-medium tracking-wide uppercase text-[10px]">ML-Powered Nutrition Tracking</p>
        </div>

        {error && (
          <div className="w-full p-4 mb-6 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-bold animate-in shake duration-300">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="w-full space-y-5">
          {!isLogin && (
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Full Name</label>
              <div className="relative">
                <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/40">person_outline</span>
                <input 
                  required={!isLogin}
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all" 
                  placeholder="John Doe" 
                />
              </div>
            </div>
          )}

          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Email Address</label>
            <div className="relative">
              <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/40">alternate_email</span>
              <input 
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all" 
                placeholder="name@example.com" 
                type="email" 
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <div className="flex justify-between items-center px-1">
              <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">Password</label>
              <span className="text-[10px] font-black text-white/40 cursor-pointer uppercase tracking-widest">Forgot?</span>
            </div>
            <div className="relative">
              <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/40">lock_open</span>
              <input 
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-12 focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all" 
                placeholder="••••••••" 
                type="password" 
              />
              <button type="button" className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40">
                <span className="material-icons-round text-xl">visibility</span>
              </button>
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-primary text-black font-black py-5 rounded-2xl shadow-[0_8px_30px_rgba(19,236,55,0.3)] hover:brightness-110 active:scale-[0.98] transition-all mt-4 uppercase tracking-[0.2em] text-xs"
          >
            {isLogin ? 'Sign In' : 'Create Account'}
          </button>
        </form>

        <div className="w-full flex items-center my-10 space-x-4">
          <div className="flex-1 h-px bg-white/5"></div>
          <span className="text-white/20 text-[9px] font-black uppercase tracking-[0.3em]">Quick Connect</span>
          <div className="flex-1 h-px bg-white/5"></div>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full">
          <button 
            type="button"
            onClick={handleGoogleLogin}
            className="flex items-center justify-center space-x-3 bg-white/5 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-colors active:scale-95"
          >
            <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-5 h-5" alt="Google" />
            <span className="text-xs font-black uppercase tracking-widest">Google</span>
          </button>
          <button 
            type="button"
            className="flex items-center justify-center space-x-3 bg-white/5 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-colors active:scale-95"
          >
            <span className="material-icons-round">apple</span>
            <span className="text-xs font-black uppercase tracking-widest">Apple</span>
          </button>
        </div>

        <div className="mt-auto pt-12 pb-6 text-center">
          <p className="text-white/40 text-[10px] font-black uppercase tracking-widest">
            {isLogin ? "Need an account?" : "Have an account?"}
            <button 
              onClick={() => setIsLogin(!isLogin)}
              className="text-primary font-black ml-2 hover:underline focus:outline-none"
            >
              {isLogin ? 'Join Now' : 'Login'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

