import React, { useState } from 'react';
import { auth } from '../services/firebase';
// Fix: Consolidated firebase/auth imports to a single line to fix member resolution errors
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, GoogleAuthProvider, signInWithPopup } from 'firebase/auth';

interface AuthProps {
  onLogin: (name: string, email: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      if (isLogin) {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        onLogin(userCredential.user.displayName || 'User', userCredential.user.email || '');
      } else {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        onLogin(name || 'New User', userCredential.user.email || '');
      }
    } catch (err: any) {
      setError(err.message || 'Authentication failed. Please check your credentials.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(auth, provider);
      onLogin(result.user.displayName || 'Google User', result.user.email || '');
    } catch (err: any) {
      setError(err.message || 'Google login failed.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-background-dark">
      {isLoading && (
        <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center">
          <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
          <p className="mt-4 text-primary font-bold animate-pulse uppercase tracking-widest text-xs">Authenticating...</p>
        </div>
      )}

      <div className="w-full max-w-[430px] flex flex-col items-center p-8 relative overflow-hidden">
        <div className="absolute top-[-10%] left-[-20%] w-[80%] h-[80%] bg-primary/20 blur-[120px] rounded-full -z-10"></div>
        <div className="absolute bottom-[-10%] right-[-20%] w-[60%] h-[60%] bg-primary/10 blur-[100px] rounded-full -z-10"></div>

        <div className="mt-20 mb-12 text-center">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-primary/10 rounded-2xl mb-4 border border-primary/20 shadow-[0_0_30px_rgba(19,236,55,0.2)]">
            <span className="material-icons-round text-primary text-5xl">bolt</span>
          </div>
          <h1 className="text-4xl font-black tracking-tight italic">NutriVision <span className="text-primary not-italic">AI</span></h1>
          <p className="text-white/40 mt-2 font-medium tracking-wide uppercase text-[10px]">ML-Powered Nutrition Tracking</p>
        </div>

        {error && (
          <div className="w-full p-4 mb-6 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-bold animate-in shake duration-300">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="w-full space-y-5">
          {!isLogin && (
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Full Name</label>
              <div className="relative">
                <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/40">person_outline</span>
                <input 
                  required={!isLogin}
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all" 
                  placeholder="John Doe" 
                />
              </div>
            </div>
          )}

          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Email Address</label>
            <div className="relative">
              <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/40">alternate_email</span>
              <input 
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-4 focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all" 
                placeholder="name@example.com" 
                type="email" 
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <div className="flex justify-between items-center px-1">
              <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">Password</label>
              <span className="text-[10px] font-black text-white/40 cursor-pointer uppercase tracking-widest">Forgot?</span>
            </div>
            <div className="relative">
              <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/40">lock_open</span>
              <input 
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 pl-12 pr-12 focus:ring-1 focus:ring-primary focus:border-primary outline-none transition-all" 
                placeholder="••••••••" 
                type="password" 
              />
              <button type="button" className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40">
                <span className="material-icons-round text-xl">visibility</span>
              </button>
            </div>
          </div>

          <button 
            type="submit"
            className="w-full bg-primary text-black font-black py-5 rounded-2xl shadow-[0_8px_30px_rgba(19,236,55,0.3)] hover:brightness-110 active:scale-[0.98] transition-all mt-4 uppercase tracking-[0.2em] text-xs"
          >
            {isLogin ? 'Sign In' : 'Create Account'}
          </button>
        </form>

        <div className="w-full flex items-center my-10 space-x-4">
          <div className="flex-1 h-px bg-white/5"></div>
          <span className="text-white/20 text-[9px] font-black uppercase tracking-[0.3em]">Quick Connect</span>
          <div className="flex-1 h-px bg-white/5"></div>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full">
          <button 
            type="button"
            onClick={handleGoogleLogin}
            className="flex items-center justify-center space-x-3 bg-white/5 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-colors active:scale-95"
          >
            <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-5 h-5" alt="Google" />
            <span className="text-xs font-black uppercase tracking-widest">Google</span>
          </button>
          <button 
            type="button"
            className="flex items-center justify-center space-x-3 bg-white/5 border border-white/10 py-4 rounded-2xl hover:bg-white/10 transition-colors active:scale-95"
          >
            <span className="material-icons-round">apple</span>
            <span className="text-xs font-black uppercase tracking-widest">Apple</span>
          </button>
        </div>

        <div className="mt-auto pt-12 pb-6 text-center">
          <p className="text-white/40 text-[10px] font-black uppercase tracking-widest">
            {isLogin ? "Need an account?" : "Have an account?"}
            <button 
              onClick={() => setIsLogin(!isLogin)}
              className="text-primary font-black ml-2 hover:underline focus:outline-none"
            >
              {isLogin ? 'Join Now' : 'Login'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useRef } from 'react';
import { UserProfile } from '../types';
import { auth } from '../services/firebase';
// Fix: Corrected import of signOut from firebase/auth to ensure the member is correctly recognized
import { signOut } from 'firebase/auth';

interface ProfileProps {
  user: UserProfile;
  onUpdate: (updates: Partial<UserProfile>) => void;
}

const PRESET_AVATARS = [
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Felix',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Aneka',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Tigger',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Spooky',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Buddy',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Cookie',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Milo',
  'https://api.dicebear.com/7.x/avataaars/svg?seed=Lilly',
];

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

const Profile: React.FC<ProfileProps> = ({ user, onUpdate }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isEditingCalories, setIsEditingCalories] = useState(false);
  const [tempCalories, setTempCalories] = useState(user.dailyCalorieGoal);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const goals = [
    { id: 'Cut', icon: 'trending_down', label: 'Lose Weight', desc: 'Calorie deficit' },
    { id: 'Maintain', icon: 'trending_flat', label: 'Stay Fit', desc: 'Equal intake' },
    { id: 'Bulk', icon: 'trending_up', label: 'Build Muscle', desc: 'Calorie surplus' },
  ];

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    setUploadError(null);

    if (file) {
      if (!file.type.startsWith('image/')) {
        setUploadError('Please select a valid image file (PNG, JPG, etc.)');
        return;
      }
      if (file.size > MAX_FILE_SIZE) {
        setUploadError('Image is too large. Please select a file under 5MB.');
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        onUpdate({ avatarUrl: reader.result as string });
        setIsModalOpen(false);
      };
      reader.onerror = () => {
        setUploadError('Error reading file. Please try again.');
      };
      reader.readAsDataURL(file);
    }
  };

  const selectPreset = (url: string) => {
    setUploadError(null);
    onUpdate({ avatarUrl: url });
    setIsModalOpen(false);
  };

  const generateNewDiceBear = () => {
    setUploadError(null);
    const randomSeed = Math.random().toString(36).substring(7);
    onUpdate({ avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=${randomSeed}` });
    setIsModalOpen(false);
  };

  const handleSaveCalories = () => {
    onUpdate({ dailyCalorieGoal: tempCalories });
    setIsEditingCalories(false);
  };

  const openModal = () => {
    setUploadError(null);
    setIsModalOpen(true);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col items-center text-center">
        <div className="relative group mb-4">
           <div className="absolute -inset-1 bg-gradient-to-tr from-primary to-primary/20 rounded-[2rem] blur opacity-25 group-hover:opacity-50 transition duration-500"></div>
           <div className="relative w-28 h-28 rounded-[2rem] bg-background-dark border-2 border-white/5 p-1 shadow-2xl overflow-hidden">
              <img 
                src={user.avatarUrl || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} 
                alt="Profile" 
                className="w-full h-full rounded-[1.8rem] bg-surface-dark object-cover" 
              />
              <button 
                onClick={openModal}
                className="absolute -bottom-2 -right-2 w-10 h-10 bg-primary rounded-2xl flex items-center justify-center text-black shadow-lg border-4 border-background-dark active:scale-90 transition-transform"
              >
                <span className="material-icons-round text-xl">camera_alt</span>
              </button>
           </div>
        </div>
        <h1 className="text-2xl font-black tracking-tight">{user.name}</h1>
        <p className="text-sm text-slate-500 font-medium">Premium Member since Oct 2024</p>
      </header>

      {/* Avatar Customization Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="glass-card w-full max-w-sm rounded-[2.5rem] p-6 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden relative">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-black tracking-tight text-white">Choose Avatar</h3>
              <button onClick={() => setIsModalOpen(false)} className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center text-white/40 hover:text-white transition-colors">
                <span className="material-icons-round text-lg">close</span>
              </button>
            </div>

            <div className="space-y-6">
              {uploadError && (
                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 animate-in shake duration-300">
                  <span className="material-icons-round text-red-400 text-sm">error_outline</span>
                  <p className="text-[10px] font-bold text-red-400 uppercase tracking-wider">{uploadError}</p>
                </div>
              )}

              <button 
                onClick={() => fileInputRef.current?.click()}
                className={`w-full flex items-center p-4 bg-primary/10 border border-primary/20 rounded-2xl group active:scale-[0.98] transition-all ${uploadError ? 'ring-1 ring-red-500/50' : ''}`}
              >
                <div className="w-10 h-10 rounded-xl bg-primary text-black flex items-center justify-center mr-4">
                  <span className="material-icons-round">upload</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-primary uppercase tracking-wider">Upload Photo</p>
                  <p className="text-[10px] text-slate-500 font-bold">Select from your gallery (Max 5MB)</p>
                </div>
                <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
              </button>

              <div className="space-y-3">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Premium Presets</p>
                <div className="grid grid-cols-4 gap-3">
                  {PRESET_AVATARS.map((url, i) => (
                    <button 
                      key={i} 
                      onClick={() => selectPreset(url)}
                      className={`aspect-square rounded-xl bg-white/5 border-2 transition-all active:scale-90 ${user.avatarUrl === url ? 'border-primary' : 'border-transparent hover:border-white/10'}`}
                    >
                      <img src={url} alt={`Preset ${i}`} className="w-full h-full p-1" />
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={generateNewDiceBear}
                className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors group"
              >
                <div className="w-10 h-10 rounded-xl bg-white/10 text-white/60 flex items-center justify-center mr-4 group-hover:text-primary transition-colors">
                  <span className="material-icons-round">casino</span>
                </div>
                <div className="text-left">
                  <p className="text-sm font-black text-white/80 uppercase tracking-wider">Surprise Me</p>
                  <p className="text-[10px] text-slate-500 font-bold">Generate a random character</p>
                </div>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Goal Selection */}
      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Active Goal</h2>
        <div className="grid grid-cols-1 gap-3">
          {goals.map((g) => (
            <button
              key={g.id}
              onClick={() => onUpdate({ goal: g.id as any })}
              className={`flex items-center p-4 rounded-3xl border transition-all ${
                user.goal === g.id 
                  ? 'bg-primary/10 border-primary shadow-[0_0_20px_rgba(19,236,55,0.1)]' 
                  : 'bg-white/5 border-white/5 hover:border-white/10'
              }`}
            >
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mr-4 ${user.goal === g.id ? 'bg-primary text-black' : 'bg-white/5 text-slate-500'}`}>
                <span className="material-icons-round text-2xl">{g.icon}</span>
              </div>
              <div className="text-left flex-1">
                <p className={`font-black tracking-tight ${user.goal === g.id ? 'text-primary' : 'text-white'}`}>{g.label}</p>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{g.desc}</p>
              </div>
              {user.goal === g.id && (
                <span className="material-icons-round text-primary">check_circle</span>
              )}
            </button>
          ))}
        </div>
      </section>

      {/* Targets */}
      <section className="space-y-4">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Daily Targets</h2>
        <div className="glass-card rounded-[2rem] p-6 border border-white/5 space-y-6">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Calories</p>
              {isEditingCalories ? (
                <div className="flex items-center space-x-2">
                  <input 
                    type="number"
                    value={tempCalories}
                    onChange={(e) => setTempCalories(Number(e.target.value))}
                    className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white"
