                    onChange={(e) => setTempCalories(Number(e.target.value))}
                    className="bg-white/5 border border-primary/30 rounded-lg py-1 px-3 text-xl font-black w-28 focus:outline-none focus:ring-1 focus:ring-primary text-white"
