          </div>

          <div className="grid grid-cols-2 gap-6 pt-6 border-t border-white/5">
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Current Weight</p>
              <p className="text-lg font-black">{user.weight || 72.5} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Target Weight</p>
              <p className="text-lg font-black text-primary">{user.targetWeight || 70.0} <span className="text-xs font-medium text-slate-500 ml-1">kg</span></p>
            </div>
          </div>
        </div>
      </section>

      {/* Settings List */}
      <section className="space-y-3 pb-10">
        <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Settings & Sync</h2>
        {[
          { icon: 'notifications', label: 'Reminders & Notifications', color: 'text-blue-400' },
          { icon: 'health_and_safety', label: 'Apple Health / Google Fit', color: 'text-red-400' },
          { icon: 'share', label: 'Invite Friends', color: 'text-orange-400' },
          { icon: 'logout', label: 'Sign Out', color: 'text-white/40', action: () => signOut(auth) },
        ].map((item, i) => (
          <button 
            key={i} 
            onClick={item.action}
            className="w-full flex items-center p-4 bg-white/5 border border-white/5 rounded-2xl hover:bg-white/10 transition-colors group"
