  name: string;
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  fiber: number;
  portionSize: string;
  timestamp: Date;
}

export interface NutritionData {
  foodName: string;
  calories: number;
  protein: number;
  carbs: number;
  fats: number;
  fiber: number;
  portionDescription: string;
}

export type View = 'home' | 'analytics' | 'diary' | 'recipes' | 'profile' | 'camera' | 'auth';

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import CameraScan from './components/CameraScan';
import Auth from './components/Auth';
import Diary from './components/Diary';
import Profile from './components/Profile';
import FoodGuide from './components/FoodGuide';
import { View, UserProfile, FoodEntry, NutritionData } from './types';
// Fix: Removed .ts extension in local imports for compatibility
import { db, auth } from './services/firebase';
import { collection, addDoc, query, where, onSnapshot, doc, setDoc, getDoc } from 'firebase/firestore';

// Helper to safely convert Firestore Timestamp to JS Date
const timestampToDate = (ts: any) => {
  if (!ts) return new Date();
  if (typeof ts.toDate === 'function') return ts.toDate();
  return new Date(ts);
};

export default function App() {
  const [view, setView] = useState<View>('auth');
  const [waterGlasses, setWaterGlasses] = useState(0);

  const [user, setUser] = useState<UserProfile>({
    name: 'Alex',
    goal: 'Maintain',
    dailyCalorieGoal: 2250,
    dailyStepGoal: 10000,
    currentSteps: 8432,
    weight: 72.5,
    targetWeight: 70.0,
    bmi: 23.4,
    bodyFat: 18.5,
    avatarUrl: `https://api.dicebear.com/7.x/avataaars/svg?seed=Alex`,
    macros: {
      protein: 150,
      carbs: 250,
      fats: 75,
      fiber: 35
    }
  });

  const [entries, setEntries] = useState<FoodEntry[]>([]);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser) {
        setView('home');

        // Load User Profile from Firestore
        const userDocRef = doc(db, 'profiles', firebaseUser.uid);
        const userSnap = await getDoc(userDocRef);

        if (userSnap.exists()) {
          const userData = userSnap.data() as UserProfile;
          setUser(prev => ({ ...prev, ...userData }));
        }

        // Load Food Entries in real-time
        const q = query(collection(db, 'entries'), where('userId', '==', firebaseUser.uid));
        const unsubFirestore = onSnapshot(q, (snapshot) => {
          const loadedEntries = snapshot.docs.map(doc => ({
            ...doc.data(),
            id: doc.id,
            timestamp: timestampToDate(doc.data().timestamp)
          })) as FoodEntry[];
          setEntries(loadedEntries);
        });

        return () => unsubFirestore();
      } else {
        setView('auth');
      }
    });

    return () => unsubscribe();
  }, []);

  const handleAddEntry = async (data: NutritionData & { multiplier?: number }) => {
    const firebaseUser = auth.currentUser;
    if (!firebaseUser) return;

    try {
      await addDoc(collection(db, 'entries'), {
        userId: firebaseUser.uid,
        name: data.foodName,
        calories: data.calories,
        protein: data.protein,
        carbs: data.carbs,
        fats: data.fats,
        fiber: data.fiber || 0,
        portionSize: data.portionDescription || '1 serving',
        timestamp: new Date()
      });
      setView('home');
    } catch (err) {
      console.error("Firestore Error:", err);
    }
  };

  const handleLogin = async (name: string, email: string) => {
    const firebaseUser = auth.currentUser;
    if (firebaseUser) {
      // Create initial profile if it doesn't exist
      await setDoc(doc(db, 'profiles', firebaseUser.uid), {
        name,
        uid: firebaseUser.uid,
        updatedAt: new Date()
      }, { merge: true });
    }
  };

  const updateUser = async (updates: Partial<UserProfile>) => {
    const firebaseUser = auth.currentUser;
    setUser(prev => ({ ...prev, ...updates }));

    if (firebaseUser) {
      try {
        await setDoc(doc(db, 'profiles', firebaseUser.uid), updates, { merge: true });
      } catch (err) {
        console.error("Firestore Update Error:", err);
      }
    }
  };

  const renderContent = () => {
    switch (view) {
      case 'home':
        return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
      case 'analytics':
        return <Analytics user={user} />;
      case 'diary':
        return <Diary entries={entries} onAddManualEntry={handleAddEntry} />;
      case 'profile':
        return <Profile user={user} onUpdate={updateUser} />;
      case 'recipes':
        return <FoodGuide user={user} />;
      case 'camera':
        return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      case 'auth':
        return <Auth onLogin={handleLogin} />;
      default:
        return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
}

import React, { useMemo } from 'react';
// Fix: Removed .ts extension in local imports for better compatibility
import { FoodEntry, UserProfile } from '../types';

interface DashboardProps {
  user: UserProfile;
  entries: FoodEntry[];
  waterGlasses: number;
  setWaterGlasses: (val: number) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, entries, waterGlasses, setWaterGlasses }) => {
  const consumed = entries.reduce((acc, entry) => acc + entry.calories, 0);
  const isSurplus = consumed > user.dailyCalorieGoal;
  const remaining = Math.max(0, user.dailyCalorieGoal - consumed);
  const surplus = isSurplus ? consumed - user.dailyCalorieGoal : 0;

  const progressPercent = Math.min(100, (consumed / user.dailyCalorieGoal) * 100);

  const totalMacros = useMemo(() => entries.reduce((acc, e) => ({
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
    fi: acc.fi + (e.fiber || 0),
  }), { p: 0, c: 0, f: 0, fi: 0 }), [entries]);

  // Step calculations
  const stepProgress = Math.min(100, (user.currentSteps / user.dailyStepGoal) * 100);

  // Analysis Engine Logic
  const getSuggestions = () => {
    const tips = [];

    // Protein check
    const proteinDeficit = user.macros.protein - totalMacros.p;
    if (proteinDeficit > 20) {
      tips.push({
        icon: 'egg',
        text: `Today protein ${Math.round(proteinDeficit)}g takkuva undi. Add 2 boiled eggs or a protein shake.`,
        color: 'text-primary'
      });
    }

    // Fiber check
    const fiberDeficit = user.macros.fiber - totalMacros.fi;
    if (fiberDeficit > 10) {
      tips.push({
        icon: 'eco',
        text: `Fiber intake is low. Consider adding some oats, sprouts, or an apple for your next meal.`,
        color: 'text-green-400'
      });
    }

    // Calorie check
    if (consumed > user.dailyCalorieGoal * 0.9 && !isSurplus) {
      tips.push({
        icon: 'warning',
        text: `You're close to your calorie limit. Opt for light snacks like cucumbers or fox nuts (makhana).`,
        color: 'text-yellow-400'
      });
    }

    // Water check
    if (waterGlasses < 4) {
      tips.push({
        icon: 'water_drop',
        text: `Only ${waterGlasses} glasses of water? Hydration helps in metabolism. Drink up!`,
        color: 'text-blue-400'
      });
    }

    if (tips.length === 0) {
      tips.push({
        icon: 'verified',
        text: `Great progress! You're hitting all your targets perfectly so far. Keep it up!`,
        color: 'text-primary'
      });
    }

    return tips;
  };

  const suggestions = useMemo(() => getSuggestions(), [totalMacros, consumed, waterGlasses, user]);

  // Main Circle Constants
  const mainSize = 200;
  const mainCenter = mainSize / 2;
  const mainRadius = 85;
  const mainCircumference = 2 * Math.PI * mainRadius;
  const mainOffset = mainCircumference - (progressPercent / 100) * mainCircumference;

  const MacroCard = ({ label, current, goal, colorClass }: { label: string, current: number, goal: number, colorClass: string }) => {
    const macroPercent = Math.min(100, (current / goal) * 100);
    const smallSize = 64;
    const smallCenter = smallSize / 2;
    const smallRadius = 26;
    const smallCircumference = 2 * Math.PI * smallRadius;
    const smallOffset = smallCircumference - (macroPercent / 100) * smallCircumference;

    return (
      <div className="glass-card rounded-2xl p-4 flex flex-col items-center border border-white/5 shadow-sm transition-all hover:bg-white/[0.05]">
        <div className="relative w-16 h-16 mb-2">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${smallSize} ${smallSize}`}>
            <circle 
              className="text-white/[0.03]" 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeWidth="5"
            />
            <circle 
              className={colorClass} 
              cx={smallCenter} 
              cy={smallCenter} 
              fill="transparent" 
              r={smallRadius} 
              stroke="currentColor" 
              strokeDasharray={smallCircumference} 
              strokeDashoffset={smallOffset} 
              strokeLinecap="round" 
              strokeWidth="5"
              style={{ transition: 'stroke-dashoffset 0.5s ease-out' }}
            />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-[10px] font-bold tracking-tighter">{Math.round(macroPercent)}%</span>
          </div>
        </div>
        <p className="text-[11px] font-semibold text-white/80">{label}</p>
        <p className="text-[10px] text-slate-500 font-medium">
          {Math.round(current)}g <span className="opacity-50">/ {goal}g</span>
        </p>
      </div>
    );
  };

  return (
    <div className="space-y-7">
      <header className="flex justify-between items-center">
        <div>
          <p className="text-[10px] font-bold text-primary uppercase tracking-[0.2em] mb-1">
            {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
          </p>
          <h1 className="text-2xl font-black tracking-tight">Hey, {user.name.split(' ')[0]}!</h1>
        </div>
        <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-primary/20 to-primary/5 p-[1px] shadow-lg">
          <div className="w-full h-full rounded-[14px] bg-background-dark overflow-hidden flex items-center justify-center">
            <img 
              src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${user.name}`} 
              alt="Avatar" 
              className="w-full h-full object-cover" 
            />
          </div>
        </div>
      </header>

      {/* AI Daily Analysis Suggestion */}
      <section className="animate-in fade-in slide-in-from-top-4 duration-500">
        <div className="bg-primary/10 border border-primary/20 rounded-2xl p-4 relative overflow-hidden">
          <div className="absolute -right-4 -top-4 opacity-10">
            <span className="material-icons-round text-7xl">psychology</span>
          </div>
          <div className="flex items-start space-x-3">
            <div className={`p-2 rounded-xl bg-background-dark/50 ${suggestions[0].color}`}>
              <span className="material-icons-round text-xl">{suggestions[0].icon}</span>
            </div>
            <div className="flex-1 pr-4">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-primary mb-1">Smart Analysis</h3>
              <p className="text-sm font-medium leading-relaxed text-white/90 italic">
                "{suggestions[0].text}"
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Main Calorie Ring */}
      <section className="glass-card rounded-[2rem] p-8 flex flex-col items-center justify-center relative overflow-hidden border border-white/5 shadow-2xl">
        <div className="absolute top-0 right-0 p-8 opacity-5">
          <span className="material-icons-round text-8xl">local_fire_department</span>
        </div>

        <div className="relative w-56 h-56 flex items-center justify-center">
          <svg className="w-full h-full transform -rotate-90" viewBox={`0 0 ${mainSize} ${mainSize}`}>
            <circle 
              className="text-primary/5" 
              cx={mainCenter} 
              cy={mainCenter} 
              fill="transparent" 
              r={mainRadius + 5} 
              stroke="currentColor" 
              strokeWidth="20"
              strokeOpacity="0.1"
            />
            <circle 
              className="text-white/5" 
              cx={mainCenter} 
              cy={mainCenter} 
              fill="transparent" 
              r={mainRadius} 
              stroke="currentColor" 
              strokeWidth="14"
            />
            <circle 
              className={isSurplus ? "text-red-500" : "text-primary"} 
              cx={mainCenter} 
              cy={mainCenter} 
              fill="transparent" 
              r={mainRadius} 
              stroke="currentColor" 
              strokeDasharray={mainCircumference} 
              strokeDashoffset={mainOffset} 
              strokeLinecap="round" 
              strokeWidth="14"
              style={{ 
                transition: 'stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1)',
                filter: `drop-shadow(0 0 8px ${isSurplus ? 'rgba(239, 68, 68, 0.4)' : 'rgba(19, 236, 55, 0.4)'})`
              }}
            />
          </svg>

          <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
            {isSurplus ? (
              <>
                <span className="text-4xl font-black text-red-500 tabular-nums">+{surplus.toLocaleString()}</span>
                <span className="text-[10px] text-red-400 font-bold uppercase tracking-widest mt-1">Surplus kcal</span>
              </>
            ) : (
              <>
                <span className="text-5xl font-black text-white tabular-nums tracking-tighter">{remaining.toLocaleString()}</span>
                <span className="text-[10px] text-white/40 font-bold uppercase tracking-[0.2em] mt-1">kcal left</span>
              </>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 w-full mt-10 pt-8 border-t border-white/5">
          <div className="text-center group">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1 group-hover:text-primary transition-colors">Logged</p>
            <p className="text-xl font-bold text-white tracking-tight">
              {consumed.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span>
            </p>
          </div>
          <div className="text-center group">
            <p className="text-[10px] text-white/30 uppercase font-black tracking-widest mb-1">Target</p>
            <p className="text-xl font-bold text-white tracking-tight">
              {user.dailyCalorieGoal.toLocaleString()} <span className="text-[10px] font-medium opacity-40">kcal</span>
            </p>
          </div>
        </div>
      </section>

      {/* Macros Section */}
      <section>
        <div className="flex justify-between items-center mb-5 px-1">
          <h2 className="text-[11px] font-black uppercase tracking-[0.25em] text-white/40">Nutrients Today</h2>
          <div className="w-6 h-6 rounded-full bg-white/5 flex items-center justify-center cursor-pointer hover:bg-white/10 transition-colors">
            <span className="material-icons-round text-[14px] text-white/40">info</span>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <MacroCard label="Protein" current={totalMacros.p} goal={user.macros.protein} colorClass="text-primary" />
          <MacroCard label="Carbs" current={totalMacros.c} goal={user.macros.carbs} colorClass="text-primary/70" />
          <MacroCard label="Fats" current={totalMacros.f} goal={user.macros.fats} colorClass="text-primary/90" />
          <MacroCard label="Fiber" current={totalMacros.fi} goal={user.macros.fiber} colorClass="text-primary/40" />
        </div>
      </section>

      {/* Quick Stats & Water */}
      <section className="grid grid-cols-2 gap-4">
        {/* Step Tracker */}
        <div className="glass-card rounded-2xl p-4 border border-white/5">
          <div className="flex items-center space-x-2 mb-3">
             <div className="p-1.5 bg-primary/20 rounded-lg">
                <span className="material-icons-round text-primary text-sm">directions_run</span>
             </div>
             <span className="text-[10px] font-black text-white/30 uppercase tracking-widest">Steps</span>
          </div>
          <div className="flex items-end justify-between">
            <p className="text-lg font-black tracking-tight">{user.currentSteps.toLocaleString()}</p>
            <p className="text-[10px] font-bold text-slate-500 pb-0.5">/ {user.dailyStepGoal.toLocaleString()}</p>
          </div>
          <div className="mt-2 w-full h-1 bg-white/5 rounded-full overflow-hidden">
            <div className="h-full bg-primary" style={{ width: `${stepProgress}%` }}></div>
          </div>
        </div>

        {/* Water Tracker */}
        <div className="glass-card rounded-2xl p-4 border border-white/5 relative overflow-hidden">
          <div className="flex items-center space-x-2 mb-3">
             <div className="p-1.5 bg-blue-500/20 rounded-lg">
                <span className="material-icons-round text-blue-400 text-sm">water_drop</span>
             </div>
             <span className="text-[10px] font-black text-white/30 uppercase tracking-widest">Hydration</span>
          </div>
          <div className="flex items-center justify-between">
            <p className="text-lg font-black tracking-tight">{waterGlasses} / 12</p>
            <button 
              onClick={() => setWaterGlasses(waterGlasses + 1)}
              className="w-8 h-8 rounded-lg bg-blue-500/10 text-blue-400 flex items-center justify-center active:scale-90 transition-transform"
            >
              <span className="material-icons-round text-sm">add</span>
            </button>
          </div>
          <div className="mt-2 flex space-x-[2px]">
            {Array.from({ length: 12 }).map((_, i) => (
              <div 
                key={i} 
                className={`flex-1 h-1 rounded-full ${i < waterGlasses ? 'bg-blue-400' : 'bg-white/5'}`}
              ></div>
            ))}
          </div>
        </div>
      </section>

      <div className="pb-10"></div>
    </div>
  );
};

