          </div>
          <div className="mt-2 flex space-x-[2px]">
            {Array.from({ length: 12 }).map((_, i) => (
              <div key={i} className={`flex-1 h-1 rounded-full ${i < waterGlasses ? 'bg-blue-400' : 'bg-white/5'}`}></div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};

