import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Analytics from './components/Analytics';
import CameraScan from './components/CameraScan';
import Auth from './components/Auth';
import Diary from './components/Diary';
import Profile from './components/Profile';
import FoodGuide from './components/FoodGuide';
import { View, UserProfile, FoodEntry, NutritionData } from './types';
import { db, auth } from './services/firebase';
import { collection, addDoc, query, where, onSnapshot, doc, setDoc, getDoc } from 'firebase/firestore';

const timestampToDate = (ts: any) => {
  if (!ts) return new Date();
  if (typeof ts.toDate === 'function') return ts.toDate();
  return new Date(ts);
};

export default function App() {
  const [view, setView] = useState<View>('auth');
  const [waterGlasses, setWaterGlasses] = useState(0);

  const [user, setUser] = useState<UserProfile>({
    name: 'User',
    goal: 'Maintain',
    dailyCalorieGoal: 2200,
    dailyStepGoal: 8000,
    currentSteps: 0,
    weight: 70.0,
    targetWeight: 70.0,
    bmi: 22.0,
    bodyFat: 18.0,
    macros: { protein: 140, carbs: 200, fats: 60, fiber: 30 }
  });

  const [entries, setEntries] = useState<FoodEntry[]>([]);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser) {
        setView('home');
        const userDocRef = doc(db, 'profiles', firebaseUser.uid);
        const userSnap = await getDoc(userDocRef);

        if (userSnap.exists()) {
          const userData = userSnap.data();
          setUser(prev => ({ ...prev, ...userData }));
        }

        const q = query(collection(db, 'entries'), where('userId', '==', firebaseUser.uid));
        const unsubFirestore = onSnapshot(q, (snapshot) => {
          const loadedEntries = snapshot.docs.map(doc => ({
            ...doc.data(),
            id: doc.id,
            timestamp: timestampToDate(doc.data().timestamp)
          })) as FoodEntry[];
          setEntries(loadedEntries);
        });

        return () => unsubFirestore();
      } else {
        setView('auth');
      }
    });

    return () => unsubscribe();
  }, []);

  const handleAddEntry = async (data: NutritionData & { multiplier?: number }) => {
    const firebaseUser = auth.currentUser;
    if (!firebaseUser) return;
    try {
      await addDoc(collection(db, 'entries'), {
        userId: firebaseUser.uid,
        name: data.foodName,
        calories: data.calories,
        protein: data.protein,
        carbs: data.carbs,
        fats: data.fats,
        fiber: data.fiber || 0,
        portionSize: data.portionDescription || '1 serving',
        timestamp: new Date()
      });
      setView('home');
    } catch (err) {
      console.error("Firestore Entry Error:", err);
    }
  };

  const handleLogin = async (name: string, email: string) => {
    const firebaseUser = auth.currentUser;
    if (firebaseUser) {
      await setDoc(doc(db, 'profiles', firebaseUser.uid), {
        name,
        email,
        uid: firebaseUser.uid,
        updatedAt: new Date()
      }, { merge: true });
    }
  };

  const updateUser = async (updates: Partial<UserProfile>) => {
    const firebaseUser = auth.currentUser;
    setUser(prev => ({ ...prev, ...updates }));
    if (firebaseUser) {
      try {
        await setDoc(doc(db, 'profiles', firebaseUser.uid), updates, { merge: true });
      } catch (err) {
        console.error("Firestore Profile Update Error:", err);
      }
    }
  };

  const renderContent = () => {
    switch (view) {
      case 'home': return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
      case 'analytics': return <Analytics user={user} />;
      case 'diary': return <Diary entries={entries} onAddManualEntry={handleAddEntry} />;
      case 'profile': return <Profile user={user} onUpdate={updateUser} />;
      case 'recipes': return <FoodGuide user={user} />;
      case 'camera': return <CameraScan onAddEntry={handleAddEntry} onClose={() => setView('home')} />;
      case 'auth': return <Auth onLogin={handleLogin} />;
      default: return <Dashboard user={user} entries={entries} waterGlasses={waterGlasses} setWaterGlasses={setWaterGlasses} />;
    }
  };

  return (
    <Layout activeView={view} onViewChange={setView}>
      {renderContent()}
    </Layout>
  );
}

import React, { useState, useMemo } from 'react';
import { FoodEntry, NutritionData } from '../types';

interface DiaryProps {
  entries: FoodEntry[];
  onAddManualEntry: (data: NutritionData) => void;
}

export default function Diary({ entries, onAddManualEntry }: DiaryProps) {
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [searchQuery, setSearchQuery] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  // Manual Entry Form State
  const [formData, setFormData] = useState<NutritionData>({
    foodName: '',
    calories: 0,
    protein: 0,
    carbs: 0,
    fats: 0,
    fiber: 0,
    portionDescription: ''
  });

  // Calculate last 7 days summary
  const last7DaysSummary = useMemo(() => {
    const summary = [];
    const today = new Date();
    for (let i = 6; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const dateStr = d.toISOString().split('T')[0];
      const dayEntries = entries.filter(e => {
        const entryDate = new Date(e.timestamp).toISOString().split('T')[0];
        return entryDate === dateStr;
      });
      const totals = dayEntries.reduce((acc, e) => ({
        cal: acc.cal + e.calories,
        p: acc.p + e.protein,
        c: acc.c + e.carbs,
        f: acc.f + e.fats,
      }), { cal: 0, p: 0, c: 0, f: 0 });
      summary.push({
        date: dateStr,
        shortDay: d.toLocaleDateString('en-US', { weekday: 'short' }),
        dayNum: d.getDate(),
        ...totals
      });
    }
    return summary;
  }, [entries]);

  // Generate a week of dates centered around selected date or today
  const calendarDates = useMemo(() => {
    const dates = [];
    const today = new Date();
    const start = new Date(selectedDate);
    start.setDate(start.getDate() - 3);

    for (let i = 0; i < 7; i++) {
      const d = new Date(start);
      d.setDate(start.getDate() + i);
      dates.push({
        full: d.toISOString().split('T')[0],
        day: d.toLocaleDateString('en-US', { weekday: 'short' }).charAt(0),
        date: d.getDate(),
        isToday: d.toISOString().split('T')[0] === today.toISOString().split('T')[0]
      });
    }
    return dates;
  }, [selectedDate]);

  const filteredEntries = entries.filter(entry => {
    const entryDate = new Date(entry.timestamp).toISOString().split('T')[0];
    const matchesDate = entryDate === selectedDate;
    const matchesSearch = entry.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesDate && matchesSearch;
  }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

  const dailyTotals = filteredEntries.reduce((acc, e) => ({
    cal: acc.cal + e.calories,
    p: acc.p + e.protein,
    c: acc.c + e.carbs,
    f: acc.f + e.fats,
  }), { cal: 0, p: 0, c: 0, f: 0 });

  const handleSaveManual = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.foodName) return;
    onAddManualEntry(formData);
    setIsAdding(false);
    setFormData({ foodName: '', calories: 0, protein: 0, carbs: 0, fats: 0, fiber: 0, portionDescription: '' });
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="space-y-6">
        <div className="flex justify-between items-center px-1">
          <div>
            <h1 className="text-2xl font-black tracking-tight">Food Diary</h1>
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-primary/60 mt-0.5">Track your intake</p>
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="w-10 h-10 rounded-2xl bg-primary text-black flex items-center justify-center shadow-lg active:scale-90 transition-transform fab-glow"
          >
            <span className="material-icons-round text-2xl">add</span>
          </button>
        </div>

        {/* Visual Calendar Strip */}
        <section className="flex justify-between items-center bg-white/5 p-2 rounded-[2.5rem] border border-white/5">
          {calendarDates.map((item) => (
            <button
              key={item.full}
              onClick={() => setSelectedDate(item.full)}
              className={`flex flex-col items-center justify-center w-12 h-16 rounded-[1.8rem] transition-all duration-300 ${
                selectedDate === item.full 
                ? 'bg-primary text-black shadow-lg shadow-primary/20 scale-105' 
                : 'text-slate-500 hover:text-white'
              }`}
            >
              <span className={`text-[10px] font-black mb-1 uppercase ${selectedDate === item.full ? 'text-black/60' : 'text-slate-600'}`}>
                {item.day}
              </span>
              <span className="text-sm font-black tracking-tighter">
                {item.date}
              </span>
              {item.isToday && selectedDate !== item.full && (
                <div className="w-1 h-1 bg-primary rounded-full mt-1"></div>
              )}
            </button>
          ))}
        </section>

        {/* Last 7 Days Summary Section */}
        <section className="space-y-3">
          <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40 px-1">Weekly Snapshot</h2>
          <div className="flex space-x-3 overflow-x-auto pb-2 custom-scrollbar no-scrollbar">
            {last7DaysSummary.map((day) => (
              <div 
                key={day.date} 
                className={`min-w-[100px] glass-card rounded-2xl p-3 border ${day.date === selectedDate ? 'border-primary/40 bg-primary/5' : 'border-white/5'} flex flex-col items-center text-center`}
              >
                <p className="text-[8px] font-black uppercase tracking-widest text-slate-500 mb-1">{day.shortDay} {day.dayNum}</p>
                <p className={`text-sm font-black ${day.cal > 0 ? 'text-primary' : 'text-white/20'}`}>{day.cal}</p>
                <p className="text-[7px] uppercase font-bold text-slate-600 tracking-tighter">kcal</p>
                <div className="mt-2 flex space-x-1 opacity-60">
                  <div className={`w-1 h-1 rounded-full ${day.p > 0 ? 'bg-primary' : 'bg-white/10'}`}></div>
                  <div className={`w-1 h-1 rounded-full ${day.c > 0 ? 'bg-white/40' : 'bg-white/10'}`}></div>
                  <div className={`w-1 h-1 rounded-full ${day.f > 0 ? 'bg-white/20' : 'bg-white/10'}`}></div>
                </div>
              </div>
            ))}
          </div>
        </section>

        <div className="grid grid-cols-1 gap-3">
          <div className="glass-card rounded-2xl p-4 flex items-center justify-between border border-white/5">
            <div className="flex items-center space-x-3">
              <span className="material-icons-round text-primary/40">calendar_month</span>
              <p className="text-xs font-black uppercase tracking-widest text-white/80">
                {new Date(selectedDate).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' })}
              </p>
            </div>
            <div className="relative overflow-hidden w-8 h-8 flex items-center justify-center bg-white/5 rounded-lg">
              <span className="material-icons-round text-sm text-slate-400">edit_calendar</span>
              <input 
                type="date" 
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="absolute inset-0 opacity-0 cursor-pointer"
              />
            </div>
          </div>

          <div className="glass-card rounded-2xl p-4 flex items-center space-x-3 border border-white/5 focus-within:border-primary/50 transition-colors">
            <span className="material-icons-round text-slate-500 text-xl">search</span>
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Filter your logs..."
              className="bg-transparent text-sm font-medium focus:outline-none w-full text-white placeholder:text-slate-600"
            />
          </div>
        </div>
      </header>

      {/* Manual Entry Modal */}
      {isAdding && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-6 bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
          <div className="glass-card w-full max-w-[380px] rounded-[2.5rem] p-8 border border-white/10 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-8">
              <div>
                <h3 className="text-xl font-black tracking-tight">Quick Log</h3>
                <p className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mt-1">Manual Input</p>
              </div>
              <button onClick={() => setIsAdding(false)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 active:scale-90 transition-transform">
                <span className="material-icons-round">close</span>
              </button>
            </div>

            <form onSubmit={handleSaveManual} className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Food Name</label>
                <input 
                  autoFocus
                  required
                  value={formData.foodName}
                  onChange={e => setFormData({...formData, foodName: e.target.value})}
                  className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                  placeholder="e.g. Masala Dosa"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Calories</label>
                  <input 
                    type="number"
                    value={formData.calories || ''}
                    onChange={e => setFormData({...formData, calories: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                    placeholder="0"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase font-black text-slate-500 tracking-widest ml-1">Protein (g)</label>
                  <input 
                    type="number"
                    value={formData.protein || ''}
                    onChange={e => setFormData({...formData, protein: Number(e.target.value)})}
                    className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-5 focus:border-primary focus:ring-1 focus:ring-primary outline-none transition-all text-white"
                    placeholder="0"
                  />
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-primary text-black font-black py-5 rounded-[1.8rem] shadow-xl shadow-primary/20 mt-4 active:scale-[0.98] transition-all uppercase tracking-widest text-xs"
              >
                Log Entry
              </button>
            </form>
          </div>
        </div>
      )}

      {filteredEntries.length > 0 && !searchQuery && (
        <section className="bg-primary/5 border border-primary/20 rounded-[2rem] p-6 grid grid-cols-4 gap-4 animate-in fade-in slide-in-from-top-4 duration-500">
          <div className="text-center">
            <p className="text-[9px] text-slate-500 uppercase font-black tracking-widest mb-1">Calories</p>
            <p className="text-lg font-black text-primary">{Math.round(dailyTotals.cal)}</p>
          </div>
          <div className="text-center">
            <p className="text-[9px] text-slate-500 uppercase font-black tracking-widest mb-1">Protein</p>
            <p className="text-lg font-black text-white">{Math.round(dailyTotals.p)}<span className="text-[8px] font-bold opacity-40 ml-0.5">g</span></p>
          </div>
          <div className="text-center">
            <p className="text-[9px] text-slate-500 uppercase font-black tracking-widest mb-1">Carbs</p>
            <p className="text-lg font-black text-white">{Math.round(dailyTotals.c)}<span className="text-[8px] font-bold opacity-40 ml-0.5">g</span></p>
          </div>
          <div className="text-center">
            <p className="text-[9px] text-slate-500 uppercase font-black tracking-widest mb-1">Fats</p>
            <p className="text-lg font-black text-white">{Math.round(dailyTotals.f)}<span className="text-[8px] font-bold opacity-40 ml-0.5">g</span></p>
          </div>
        </section>
      )}

      <section className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <h2 className="text-[10px] font-black uppercase tracking-[0.25em] text-white/40">
            {searchQuery ? `Search Results (${filteredEntries.length})` : 'Timeline'}
          </h2>
        </div>

        {filteredEntries.length === 0 ? (
          <div className="py-20 flex flex-col items-center text-center space-y-6 opacity-30">
            <div className="w-20 h-20 rounded-full bg-white/5 flex items-center justify-center">
              <span className="material-icons-round text-5xl">{searchQuery ? 'search_off' : 'receipt_long'}</span>
            </div>
            <p className="text-sm font-medium px-12 leading-relaxed">
              {searchQuery ? `Nothing found matching "${searchQuery}"` : 'No logs for this date yet.'}
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredEntries.map((entry) => (
              <div key={entry.id} className="glass-card rounded-[1.8rem] p-5 flex items-center justify-between group active:scale-[0.98] transition-all border border-white/5 hover:bg-white/[0.05]">
                <div className="space-y-2 shrink overflow-hidden text-left">
                  <div className="flex items-center space-x-3">
                    <div className="px-2 py-0.5 rounded-lg bg-primary/10 text-primary text-[9px] font-black uppercase tracking-widest">
