import React, { useState } from 'react';
import { auth } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  GoogleAuthProvider, 
  signInWithPopup 
} from 'firebase/auth';

interface AuthProps {
  onLogin: (name: string, email: string) => void;
}

const Auth: React.FC<AuthProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError(null);

    try {
      if (isLogin) {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        onLogin(userCredential.user.displayName || 'User', userCredential.user.email || '');
      } else {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        onLogin(name || 'New User', userCredential.user.email || '');
      }
    } catch (err: any) {
      const errorMessage = err.code === 'auth/user-not-found' 
        ? 'No account found with this email.' 
        : err.code === 'auth/wrong-password' 
        ? 'Incorrect password. Please try again.'
        : err.message || 'Authentication failed.';
      setError(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const provider = new GoogleAuthProvider();
      const result = await signInWithPopup(auth, provider);
      onLogin(result.user.displayName || 'Google User', result.user.email || '');
    } catch (err: any) {
      setError('Google login failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex justify-center min-h-screen bg-[#0c1a0e] text-slate-100 font-sans selection:bg-primary/30">
      {/* Absolute Background Elements */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-15%] w-[70%] h-[70%] bg-primary/10 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[5%] right-[-10%] w-[60%] h-[60%] bg-primary/5 blur-[100px] rounded-full"></div>
      </div>

      <div className="w-full max-w-[430px] flex flex-col items-center px-8 py-12 relative z-10">
        {/* Branding Area */}
        <div className="w-full text-center mt-8 mb-12">
          <div className="relative inline-block mb-6">
            <div className="absolute -inset-2 bg-primary/20 blur-xl rounded-3xl animate-pulse"></div>
            <div className="relative w-20 h-20 bg-gradient-to-br from-primary/20 to-primary/5 border border-primary/20 rounded-2xl flex items-center justify-center shadow-2xl">
              <span className="material-icons-round text-primary text-5xl">auto_awesome</span>
            </div>
          </div>
          <h1 className="text-4xl font-black tracking-tight text-white mb-2">
            NutriVision <span className="text-primary italic">AI</span>
          </h1>
          <p className="text-[10px] font-black uppercase tracking-[0.4em] text-white/30">
            Intelligent Wellness Hub
          </p>
        </div>

        {/* Auth Mode Toggle */}
        <div className="w-full bg-white/[0.03] border border-white/5 p-1.5 rounded-2xl mb-8 flex items-center">
          <button 
            onClick={() => setIsLogin(true)}
            className={`flex-1 py-3 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all duration-300 ${isLogin ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Sign In
          </button>
          <button 
            onClick={() => setIsLogin(false)}
            className={`flex-1 py-3 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all duration-300 ${!isLogin ? 'bg-primary text-black shadow-lg shadow-primary/20' : 'text-slate-500 hover:text-slate-300'}`}
          >
            New Account
          </button>
        </div>

        {/* Main Form Card */}
        <div className="w-full glass-card rounded-[2.5rem] p-8 border border-white/10 shadow-2xl backdrop-blur-2xl">
          {error && (
            <div className="w-full p-4 mb-6 bg-red-500/10 border border-red-500/20 rounded-2xl flex items-center gap-3 animate-in shake duration-300">
              <span className="material-icons-round text-red-400 text-lg">error_outline</span>
              <p className="text-xs font-bold text-red-400 leading-tight">{error}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {!isLogin && (
              <div className="space-y-2">
                <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Full Name</label>
                <div className="relative group">
                  <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors">person</span>
                  <input 
                    required={!isLogin}
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4.5 pl-12 pr-4 text-sm font-medium focus:ring-1 focus:ring-primary/50 focus:border-primary/50 focus:bg-white/[0.06] outline-none transition-all placeholder:text-slate-600" 
                    placeholder="Enter your name" 
                  />
                </div>
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em] ml-1">Email Address</label>
              <div className="relative group">
                <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors">alternate_email</span>
                <input 
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4.5 pl-12 pr-4 text-sm font-medium focus:ring-1 focus:ring-primary/50 focus:border-primary/50 focus:bg-white/[0.06] outline-none transition-all placeholder:text-slate-600" 
                  placeholder="name@example.com" 
                  type="email" 
                />
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[10px] font-black text-primary uppercase tracking-[0.2em]">Password</label>
                {isLogin && <span className="text-[10px] font-bold text-white/30 hover:text-primary cursor-pointer transition-colors uppercase tracking-widest">Forgot?</span>}
              </div>
              <div className="relative group">
                <span className="material-icons-round absolute left-4 top-1/2 -translate-y-1/2 text-white/20 group-focus-within:text-primary transition-colors">lock_open</span>
                <input 
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full bg-white/[0.03] border border-white/10 rounded-2xl py-4.5 pl-12 pr-12 text-sm font-medium focus:ring-1 focus:ring-primary/50 focus:border-primary/50 focus:bg-white/[0.06] outline-none transition-all placeholder:text-slate-600" 
                  placeholder="••••••••" 
                  type="password" 
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={isLoading}
              className="w-full relative bg-primary text-black font-black py-5 rounded-[1.8rem] shadow-[0_8px_30px_rgba(19,236,55,0.3)] hover:brightness-110 active:scale-[0.98] transition-all overflow-hidden flex items-center justify-center uppercase tracking-[0.2em] text-[11px] disabled:opacity-70"
            >
              {isLoading ? (
                <div className="w-5 h-5 border-2 border-black/30 border-t-black rounded-full animate-spin"></div>
              ) : (
                <span>{isLogin ? 'Authenticate' : 'Start Journey'}</span>
              )}
            </button>
          </form>

          {/* Divider */}
          <div className="w-full flex items-center my-8 space-x-4">
            <div className="flex-1 h-px bg-white/5"></div>
            <span className="text-white/20 text-[8px] font-black uppercase tracking-[0.4em]">Fast Login</span>
            <div className="flex-1 h-px bg-white/5"></div>
          </div>

          {/* Social Logins */}
          <div className="grid grid-cols-2 gap-4 w-full">
            <button 
              type="button"
              onClick={handleGoogleLogin}
              className="flex items-center justify-center space-x-3 bg-white/[0.03] border border-white/5 py-4 rounded-2xl hover:bg-white/10 transition-all active:scale-95 group"
            >
              <img src="https://www.gstatic.com/images/branding/product/1x/gsa_512dp.png" className="w-5 h-5 grayscale group-hover:grayscale-0 transition-all" alt="Google" />
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 group-hover:text-white">Google</span>
            </button>
            <button 
              type="button"
              className="flex items-center justify-center space-x-3 bg-white/[0.03] border border-white/5 py-4 rounded-2xl hover:bg-white/10 transition-all active:scale-95 group"
            >
              <span className="material-icons-round text-slate-400 group-hover:text-white transition-colors">apple</span>
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-400 group-hover:text-white">Apple</span>
            </button>
          </div>
        </div>

        {/* Footer Info */}
        <div className="mt-12 text-center opacity-40">
          <p className="text-[9px] font-bold uppercase tracking-[0.2em] leading-relaxed">
            By continuing, you agree to our <span className="text-white hover:underline cursor-pointer">Terms of Service</span><br/>
            and <span className="text-white hover:underline cursor-pointer">Privacy Policy</span>.
          </p>
        </div>
      </div>
    </div>
  );
};

export default Auth;

